-- Associa jogadores aos perfis e objetos DadosJogador.
local DadosJogador = require(script.Parent.DadosJogador)

local DataManager = { Profiles = {} }
local objetos = {}

function DataManager.PublicarRecebimentos()
	for jogador in DataManager.Profiles do
		local dados=DataManager.ObterDados(jogador)
		if dados then dados:PublicarRecebimentos() end
	end
end

function DataManager.PublicarGanhosPorSegundo(segundos)
	for jogador in DataManager.Profiles do
		local dados = DataManager.ObterDados(jogador)
		if dados then dados:PublicarGanhosPorSegundo(segundos) end
	end
end

-- Procura uma sessao ativa do jogador e devolve o objeto DadosJogador correspondente. Reutiliza o objeto
-- enquanto o perfil for o mesmo; sem sessao ativa devolve nil.
function DataManager.ObterDados(jogador)
	local perfil = DataManager.Profiles[jogador]
	if not perfil or not perfil:IsActive() then return nil end
	local entrada = objetos[jogador]
	-- O cache evita criar um DadosJogador em cada chamada. Comparar a referencia do perfil tambem impede
	-- reutilizar um objeto associado a uma sessao substituida.
	if not entrada or entrada.perfil ~= perfil then
		entrada = { perfil = perfil, dados = DadosJogador.new(jogador, perfil) }
		objetos[jogador] = entrada
	end
	return not entrada.dados._suspenso and entrada.dados or nil
end

-- Registra a sessao aberta pelo carregamento e devolve seu objeto DadosJogador. Substituir a sessao faz
-- ObterDados descartar a associacao anterior.
function DataManager.RegistrarPerfil(jogador, perfil)
	DataManager.Profiles[jogador] = perfil
	return DataManager.ObterDados(jogador)
end

-- Remove as referencias locais ao perfil e ao objeto de dados. Encerrar a sessao do ProfileStore e
-- responsabilidade do fluxo de carregamento, nao desta limpeza do registro.
function DataManager.RemoverPerfil(jogador)
	DataManager.Profiles[jogador] = nil
	objetos[jogador] = nil
end

-- Fachada para creditar a moeda da fabrica sem expor o perfil aos componentes. Devolve false quando nao ha
-- dados ativos; caso contrario, devolve o resultado de AdicionarDinheiro.
function DataManager.AddDinheiro(jogador: Player, valor: string): boolean
	local dados = DataManager.ObterDados(jogador)
	return dados ~= nil and dados:AdicionarDinheiro(valor)
end

-- Obtem os dados ativos e encaminha a compra por identificador. Mantem a resposta sucesso/mensagem usada pelo
-- servico da loja e pela compra automatica da colocacao.
function DataManager.ComprarMaquina(jogador: Player, maquinaId: string)
	local dados = DataManager.ObterDados(jogador)
	if not dados then return false, "Dados ainda nao estao disponiveis." end
	return dados:ComprarMaquina(maquinaId)
end

-- Encaminha a venda e sua configuracao esperada ao objeto do jogador. Retorna uma recusa quando os dados ainda
-- nao estao disponiveis.
function DataManager.VenderMaquina(jogador: Player, maquinaId: string, configuracaoEsperada: string)
  local dados = DataManager.ObterDados(jogador)
  if not dados then return false, "Dados ainda nao estao disponiveis." end
  return dados:VenderMaquina(maquinaId, configuracaoEsperada)
end

function DataManager.DefinirConfiguracao(jogador: Player, id: string, valor: any)
  local dados = DataManager.ObterDados(jogador)
  if not dados then return false, "Dados ainda nao estao disponiveis." end
  return dados:DefinirConfiguracao(id, valor)
end

function DataManager.DefinirAtalho(jogador: Player, original: string, tecla: string)
  local dados = DataManager.ObterDados(jogador)
  if not dados then return false, "Dados ainda nao estao disponiveis." end
  return dados:DefinirAtalho(original, tecla)
end

function DataManager.DefinirJanela(jogador: Player, id: string, rect: any)
  local dados = DataManager.ObterDados(jogador)
  if not dados then return false, "Dados ainda nao estao disponiveis." end
  return dados:DefinirJanela(id, rect)
end

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local pacotes = ReplicatedStorage:FindFirstChild("Packages")
if pacotes and pacotes:FindFirstChild("Networker") then
  local Networker = require(pacotes.Networker)
  local CosmeticosBeta = require(script.Parent.Parent.CosmeticosBeta)
  local ServicoConfiguracoes = {}
  function ServicoConfiguracoes:SalvarOpcao(jogador, id, valor)
    return DataManager.DefinirConfiguracao(jogador, id, valor)
  end
  function ServicoConfiguracoes:SalvarAtalho(jogador, original, tecla)
    return DataManager.DefinirAtalho(jogador, original, tecla)
  end
  function ServicoConfiguracoes:SalvarJanela(jogador, id, rect)
    return DataManager.DefinirJanela(jogador, id, rect)
  end
  function ServicoConfiguracoes:EmoteBeta(jogador, tema)
    return CosmeticosBeta.Emote(jogador, tema)
  end
  Networker.server.new("Configuracoes", ServicoConfiguracoes, {
    ServicoConfiguracoes.SalvarOpcao,
    ServicoConfiguracoes.SalvarAtalho,
    ServicoConfiguracoes.SalvarJanela,
    ServicoConfiguracoes.EmoteBeta,
  })
end

return DataManager

local ProfileStore=require(script.Parent.Parent.Libraries.ProfileStore)
local nome=game:GetService("RunService"):IsStudio() and "Test" or "Live"
return ProfileStore.New(nome,require(script.Parent.Template))

-- Liga os pedidos de rede ao servico do servidor. Apenas os metodos da lista de permissoes podem ser chamados
-- pelo cliente.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Networker = require(ReplicatedStorage.Packages.Networker)
local ServicoConstrucao = require(script.Parent.ServicoConstrucao)
-- require deste modulo reutiliza o mesmo servico no servidor. Restauracao, captura e pedidos remotos
-- precisam consultar os mesmos mapas de modelos e registros.
local servico = ServicoConstrucao.new()

-- O cliente seleciona uma origem; configuracoes personalizadas sao decididas pelo servidor.
local Construcao = {}
-- Entrada interna do servidor para restaurar as construcoes de um jogador apos carregar dados ou atribuir a
-- plot. Encaminha ao servico e devolve seu resultado.
function Construcao.Restaurar(jogador)
	return servico:Restaurar(jogador)
end
-- Recebe o pedido remoto de colocacao e o encaminha integralmente ao servico. minimo e o canto na grade;
-- tokenCopia identifica uma captura do servidor e usarPadrao solicita o catalogo da loja.
function Construcao:Colocar(jogador, maquinaId, minimo, rotacao, tokenCopia, usarPadrao, elevador)
	return servico:Colocar(jogador, maquinaId, minimo, rotacao, tokenCopia, usarPadrao, elevador)
end
function Construcao:ColocarMultiplos(jogador, maquinaId, pedidos, tokenCopia, usarPadrao)
	return servico:ColocarMultiplos(jogador, maquinaId, pedidos, tokenCopia, usarPadrao)
end
-- Encaminha o modelo apontado pelo cliente; o servico decide se o jogador pode retira-lo e devolve sucesso e
-- mensagem.
function Construcao:Recolher(jogador, maquina)
	return servico:Recolher(jogador, maquina)
end
function Construcao:RecolherTudo(jogador)
  return servico:RecolherTudo(jogador)
end
function Construcao:Desfazer(jogador)
  return servico:Desfazer(jogador)
end
function Construcao:Refazer(jogador)
  return servico:Refazer(jogador)
end
function Construcao:ConfigurarElevador(jogador, maquina, altura, entrada, saida, sentido)
	return servico:ConfigurarElevador(jogador, maquina, altura, entrada, saida, sentido)
end
function Construcao:AtualizarPrevia(jogador, previa)
  return servico:AtualizarPrevia(jogador, previa)
end
-- Vende uma lista de pecas colocadas; o servico valida o dono, atualiza o perfil e so entao destroi os modelos.
function Construcao:VenderColocadas(jogador, maquinas)
	return servico:VenderMaquinasColocadas(jogador, maquinas)
end
-- Solicita ao servico a captura de uma peca do terreno. A resposta inclui uma configuracao para a previa e um
-- token, sem conceder ao cliente permissao para definir as melhorias.
function Construcao:Copiar(jogador, maquina)
	return servico:Copiar(jogador, maquina)
end
-- Captura um conjunto selecionado sem apagar as fontes e devolve os dados para montar a previa azul de copia.
function Construcao:CopiarGrupo(jogador, maquinas)
	return servico:CopiarGrupo(jogador, maquinas)
end
-- Confirma todas as copias da previa numa operacao validada pelo servidor.
function Construcao:ColocarGrupoCopia(jogador, token, pedidos)
	return servico:ColocarGrupoCopia(jogador, token, pedidos)
end
-- Encaminha a captura e o salvamento persistente das pecas selecionadas como um blueprint.
function Construcao:CriarBlueprint(jogador, nome, maquinas)
	return servico:CriarBlueprint(jogador, nome, maquinas)
end
-- Devolve somente os nomes e a quantidade de pecas de cada blueprint do jogador.
function Construcao:ListarBlueprints(jogador)
	return servico:ListarBlueprints(jogador)
end
-- Gera um token temporario para posicionar uma copia do blueprint escolhido usando a compra em grupo existente.
function Construcao:PrepararBlueprint(jogador, identificador)
  return servico:PrepararBlueprint(jogador, identificador)
end
function Construcao:SubstituirBlueprint(jogador, identificador, nome, maquinas)
  return servico:SubstituirBlueprint(jogador, identificador, nome, maquinas)
end
function Construcao:EditarBlueprint(jogador, identificador, nome, indicesMantidos)
  return servico:EditarBlueprint(jogador, identificador, nome, indicesMantidos)
end
function Construcao:RenomearBlueprint(jogador, identificador, nome)
  return servico:RenomearBlueprint(jogador, identificador, nome)
end
function Construcao:DeletarBlueprint(jogador, identificador)
  return servico:DeletarBlueprint(jogador, identificador)
end
function Construcao:MoverBlueprint(jogador, identificador, deslocamento)
  return servico:MoverBlueprint(jogador, identificador, deslocamento)
end
-- Valida, captura e apaga as instancias selecionadas antes de iniciar a previa; devolve um token temporario.
function Construcao:IniciarMovimento(jogador, maquinas)
	return servico:IniciarMovimento(jogador, maquinas)
end
-- Finaliza o token de uma peca e cria uma nova instancia no destino validado pelo servico.
function Construcao:Mover(jogador, token, minimo, rotacao)
	return servico:Mover(jogador, token, minimo, rotacao)
end
-- Confirma os destinos do grupo em lote ou deixa o movimento pendente para uma nova tentativa.
function Construcao:MoverGrupo(jogador, token, movimentos)
	return servico:MoverGrupo(jogador, token, movimentos)
end
-- Encerra o token pendente e devolve as personalizacoes capturadas ao inventario.
function Construcao:CancelarMovimento(jogador, token)
	return servico:CancelarMovimento(jogador, token)
end
-- API interna para scripts do servidor alterarem uma peca de forma validada. Nao esta na lista de metodos
-- remotos; uma interface futura de melhorias precisa de pedidos especificos autorizados pelo servidor.
function Construcao.Personalizar(jogador, maquina, modificacoes)
	return servico:Personalizar(jogador, maquina, modificacoes)
end
-- Pede a captura das diferencas atuais dos modelos nos registros do perfil. E chamada pelo fluxo de salvamento
-- e nao retorna uma lista para o cliente.
function Construcao.Sincronizar(jogador)
	servico:Sincronizar(jogador)
end

function Construcao.Administrar(jogador,pedido) return servico:Administrar(jogador,pedido) end
function Construcao.RedimensionarAdministrativo(jogador,nivel) return servico:RedimensionarAdministrativo(jogador,nivel) end

-- Apenas servicos do servidor podem coordenar um reinicio; este metodo nao pertence a lista remota.
function Construcao.ReiniciarProgresso(jogador, alterarDados)
	return servico:ReiniciarProgresso(jogador, alterarDados)
end

Players.PlayerRemoving:Connect(function(jogador)
	servico:LimparJogador(jogador)
end)
-- Esta lista autoriza somente os metodos abaixo pela rede. O jogador e fornecido pelo canal; Personalizar,
-- Restaurar e Sincronizar continuam acessiveis apenas a scripts do servidor.
Networker.server.new("Construcao", Construcao, {
	Construcao.Colocar, Construcao.Recolher, Construcao.Copiar, Construcao.CopiarGrupo,
Construcao.ColocarGrupoCopia, Construcao.CriarBlueprint, Construcao.ListarBlueprints,
  Construcao.PrepararBlueprint, Construcao.SubstituirBlueprint, Construcao.EditarBlueprint,
  Construcao.RenomearBlueprint, Construcao.DeletarBlueprint, Construcao.MoverBlueprint,
  Construcao.IniciarMovimento,
	Construcao.Mover, Construcao.MoverGrupo, Construcao.CancelarMovimento, Construcao.VenderColocadas,
Construcao.ColocarMultiplos,
  Construcao.RecolherTudo,
Construcao.Desfazer,
  Construcao.Refazer,
  Construcao.AtualizarPrevia,
  Construcao.ConfigurarElevador,
})
return Construcao

local Players = game:GetService("Players")
local ServicoPrestigio = {}
ServicoPrestigio.__index = ServicoPrestigio

-- Reutiliza a coordenacao de dados/plot; nao cria outra instancia do servico de construcao.
function ServicoPrestigio.new(construcao)
	return setmetatable({ _construcao = construcao }, ServicoPrestigio)
end

-- A rede fornece o jogador real. O unico argumento e o ciclo que a ficha mostrava; quantidade de
-- vidas, custo, saldo e patrimonio preservado sao decididos pelo servidor.
function ServicoPrestigio:Reencarnar(jogador, indiceEsperado)
	if jogador.Parent ~= Players then return false, "Jogador indisponivel." end
	if type(indiceEsperado) ~= "number" or indiceEsperado < 0 or indiceEsperado >= 2 ^ 53 - 1
		or indiceEsperado % 1 ~= 0 then return false, "Reencarnacao invalida." end
	return self._construcao.ReiniciarProgresso(jogador, function(dados)
		return dados:Reencarnar(indiceEsperado)
	end)
end

return ServicoPrestigio

local sufixos = { "", "K", "M", "B", "T", "Qd", "Qn", "Sx", "Sp", "O", "N" } local unidades = { "", "U", "D", "T", "Qa", "Qi", "Sx", "Sp", "O", "N" } local dezenas = { "De", "Vi", "Tg", "Qag", "Qig", "Sxg", "Spg", "Og", "Ng", "Ce" }
for indice = 10, 101 do local unidade = unidades[indice % 10 + 1] local dezena = dezenas[math.floor(indice / 10)] local nome = unidade .. dezena sufixos[indice + 2] = nome end
-- Somente apresentacao; compra, saldo e ordenacao conservam o inteiro decimal completo. return function(valor, preservarPrecisao) if type(valor) == "number" and valor >= 0 and valor < 2 ^ 53 and valor % 1 == 0 then valor = string.format("%.0f", valor) end assert(type(valor) == "string" and valor:match("^%d+$"), "Inteiro decimal invalido.") valor = valor:gsub("^0+", "") if valor == "" then return "0" end if #valor <= 3 then return valor end local grupo = math.floor((#valor - 1) / 3) local inteiros = #valor - grupo * 3 local fracao = valor:sub(inteiros + 1, preservarPrecisao and #valor or inteiros + 2):gsub("0+$", "") return valor:sub(1, inteiros) .. (fracao ~= "" and "," .. fracao or "") .. (sufixos[grupo + 1] or ("e" .. grupo * 3)) end

local Classificacao = {}
Classificacao.Categorias = {
	{ Id = "Vidas", Nome = "Vidas", Monetario = false },
	{ Id = "DinheiroPorSegundo", Nome = "Dinheiro/s", Monetario = true },
	{ Id = "Minerio", Nome = "Minério", Monetario = true },
	{ Id = "Dinheiro", Nome = "Dinheiro", Monetario = true },
}
Classificacao.Limite = 50

function Classificacao.Normalizar(valor)
	if type(valor) ~= "string" or not valor:match("^[0-9]+$") then return nil end
	if valor:sub(1, 1) ~= "0" then return valor end
	local normalizado = valor:gsub("^0+", "")
	return normalizado ~= "" and normalizado or "0"
end

function Classificacao.Maior(a, b)
	return #a > #b or (#a == #b and a > b)
end

function Classificacao.Mesclar(anterior, novos)
	local porJogador = {}
	for _, lista in { anterior or {}, novos or {} } do
		for _, registro in lista do
			local valor = Classificacao.Normalizar(registro.Valor)
			if not valor or valor == "0" then continue end
			local salvo = porJogador[registro.UserId]
			local geracao=registro.Geracao or 0
			if not salvo or geracao>(salvo.Geracao or 0) or (geracao==(salvo.Geracao or 0) and Classificacao.Maior(valor, salvo.Valor)) then
				porJogador[registro.UserId] = { UserId = registro.UserId, Nome = registro.Nome, Valor = valor, Geracao=geracao }
			end
		end
	end
	local lista = {}
	for _, registro in porJogador do table.insert(lista, registro) end
	table.sort(lista, function(a, b)
		return if a.Valor == b.Valor then a.UserId < b.UserId else Classificacao.Maior(a.Valor, b.Valor)
	end)
	while #lista > Classificacao.Limite do table.remove(lista) end
	return lista
end

return Classificacao

