T.Licoes={ {Id="inicio",Titulo="Seu objetivo e o kit inicial",Nivel="Básico",Resumo="Seu objetivo e o kit inicial",Secoes={{"Como usar","Leve minério da mineradora à fornalha usando esteiras. Modificadores aumentam seu valor no caminho."},{"Lembrete","Seu kit tem 10 esteiras, uma mineradora e uma fornalha. Abra o inventário com {E} e coloque as três peças."}}}, {Id="plot",Titulo="Sua plot e a grade de construção",Nivel="Básico",Resumo="Sua plot e a grade de construção",Secoes={{"Como usar","A plot começa em {PLOT_INICIAL}³ blocos e pode chegar a {PLOT_MAX}³. A caixa da prévia mostra o espaço ocupado."},{"Lembrete","Encaixe as peças na grade. Uma prévia vermelha indica uma posição bloqueada."}}}, {Id="inventario-loja",Titulo="Inventário, loja e fichas das peças",Nivel="Básico",Resumo="Inventário, loja e fichas das peças",Secoes={{"Como usar","{E}: inventário. {F}: loja. Clique para ver estatísticas; clique duplo para colocar."},{"Lembrete","No inventário, Na plot mostra peças colocadas. Não usadas mostra tipos ausentes, com estoque e preço. Sem estoque, clique para abrir a loja."}}}, {Id="primeira-fabrica",Titulo="Monte sua primeira linha de produção",Nivel="Básico",Resumo="Monte sua primeira linha de produção",Secoes={{"Como usar","Coloque a mineradora, uma esteira sob a saída e a fornalha no fim do caminho. As setas devem levar até a bandeja."},{"Lembrete","Observe um minério chegar à fornalha. Se cair, corrija a direção, altura ou espaço entre as peças."}}}, {Id="colocacao",Titulo="Colocação, prévia e cancelamento",Nivel="Básico",Resumo="Colocação, prévia e cancelamento",Secoes={{"Como usar","Aponte a prévia e confirme: clique no PC, Confirmar no celular ou R2 no controle."},{"Lembrete","{Q}, Voltar ou B cancela. Ao cancelar uma movimentação, as peças retiradas vão para o inventário."}}}, {Id="mineradoras",Titulo="Mineradoras: valor, ritmo e saída",Nivel="Básico",Resumo="Mineradoras: valor, ritmo e saída",Secoes={{"Como usar","A mineradora cria minério pelo valor e intervalo mostrados na ficha. Menor intervalo significa mais unidades."},{"Lembrete","Coloque a correia sob a saída, que pode avançar além do corpo ou da ponta da broca."}}}, {Id="esteiras",Titulo="Esteiras, centralizadoras e paredes",Nivel="Básico",Resumo="Esteiras, centralizadoras e paredes",Secoes={{"Como usar","Conecte correias na mesma altura e confira as setas durante a colocação. Gire o próximo trecho para fazer curvas."},{"Lembrete","Centralizadoras aproximam o minério do centro. Use-as antes de passagens estreitas. Paredes podem conter ou bloquear a rota."}}}, {Id="fornalhas",Titulo="Fornalhas e pagamento",Nivel="Básico",Resumo="Fornalhas e pagamento",Secoes={{"Como usar","A bandeja recebe o minério e vende pelo efeito mostrado na ficha. Termine sua linha nela."},{"Lembrete","Confira se o minério chega à bandeja, sem bater no corpo da fornalha ou cair antes."}}}, {Id="numeros",Titulo="Dinheiro, dinheiro/s e números grandes",Nivel="Básico",Resumo="Dinheiro, dinheiro/s e números grandes",Secoes={{"Como usar","O saldo mostra seu dinheiro. Dinheiro/s é uma média recente: espere estabilizar após mudar a fábrica."},{"Lembrete","K = mil, M = milhão, B = bilhão. Passe o mouse nos números do saldo e da classificação para ler o nome completo."}}}, {Id="recuperacao-minerio",Titulo="Minério no chão ou parado",Nivel="Básico",Resumo="Minério no chão ou parado",Secoes={{"Como usar","Minério no chão ou parado por cinco segundos é vendido por apenas 1/10 do valor. Pequenas oscilações não evitam a venda."},{"Lembrete","Para ganhar mais, corrija o bloqueio e leve a produção à fornalha."}}}, {Id="pc",Titulo="Controles de PC e atalhos",Nivel="Básico",Resumo="Controles de PC e atalhos",Secoes={{"Como usar","{ATALHOS}"},{"Lembrete","Clique em uma peça para abrir ações. Arraste no chão para selecionar área. Botão do meio copia; Shift move, Ctrl recolhe e Alt vende. Remapeie teclas em Configurações."}}}, {Id="mobile-controle",Titulo="Celular e controle: como construir",Nivel="Básico",Resumo="Celular e controle: como construir",Secoes={{"Como usar","No celular, toque para apontar e use Confirmar. Para selecionar área, toque dois cantos e conclua. Subir/Descer ajusta a altura."},{"Lembrete","No controle: Y alterna menus; A ativa botões; R2 confirma; L2 marca área/linha; R1/L1/X giram; direcional muda altura; B volta."}}}, {Id="raridades",Titulo="Raridades e progressão das peças",Nivel="Intermediário",Resumo="Raridades e progressão das peças",Secoes={{"Como usar","A ficha e a borda do ícone mostram a raridade. Ela acompanha o preço na Loja, o lote no Renascimento e a receita no Craft."},{"Lembrete","Compare efeito, limites e tamanho antes de substituir uma peça."}}}, {Id="modificadores",Titulo="Modificadores: efeitos e ordem da linha",Nivel="Intermediário",Resumo="Modificadores: efeitos e ordem da linha",Secoes={{"Como usar","+25 soma 25 ao minério; ×2 dobra. A ordem importa: (100 + 25) ×2 = 250; 100 ×2 + 25 = 225."},{"Lembrete","As frações são arredondadas no minério: abaixo de 0,5 para baixo; a partir de 0,5 para cima."}}}, {Id="faixas-limites",Titulo="Faixas, usos e limite de entrada",Nivel="Intermediário",Resumo="Faixas, usos e limite de entrada",Secoes={{"Como usar","Cada faixa pode aplicar uma etapa. Duas faixas podem modificar duas vezes, mas contam como um uso da peça."},{"Lembrete","Limite combina usos por tipo e valor de entrada. O mínimo é inclusivo; o máximo é exclusivo. Cópias compartilham os usos do mesmo minério."}}}, {Id="emissores",Titulo="Modificadores sem esteira e passagens estreitas",Nivel="Intermediário",Resumo="Modificadores sem esteira e passagens estreitas",Secoes={{"Como usar","Um modificador sem esteira usa a correia de outra peça. Posicione-o para a emissão tocar o minério."},{"Lembrete","Em passagens estreitas, alinhe a chegada ou use uma centralizadora antes."}}}, {Id="acoes",Titulo="Mover, copiar, recolher e vender peças",Nivel="Intermediário",Resumo="Mover, copiar, recolher e vender peças",Secoes={{"Como usar","{Z}: recolher. {X}: mover. {C}: copiar. {V}: vender. As mesmas ações estão no cartão da peça."},{"Lembrete","Recolher guarda a peça. Copiar mantém a original e usa estoque ou dinheiro. Confira a seleção antes de vender."}}}, {Id="selecao-grupos",Titulo="Seleção de área, altura e grupos",Nivel="Intermediário",Resumo="Seleção de área, altura e grupos",Secoes={{"Como usar","Arraste com o clique esquerdo para selecionar. A roda altera a altura; Shift + roda move a camada. Shift + clique ajusta a seleção."},{"Lembrete","{Z}/{X}/{C}/{V} age diretamente no grupo. Máximo: {LIMITE_GRUPO} peças. Na movimentação parcial, peças bloqueadas voltam ao inventário."}}}, {Id="linhas",Titulo="Coloque várias peças em linha",Nivel="Intermediário",Resumo="Coloque várias peças em linha",Secoes={{"Como usar","Segure e arraste uma prévia para repetir peças em linha reta. Solte para colocar. Cada arraste segue uma das quatro direções de 90°."},{"Lembrete","No celular, use Iniciar linha; no controle, L2. Obstáculos e saldo insuficiente permitem colocar apenas a parte válida."}}}, {Id="construcao-3d",Titulo="Altura, rotações e esteiras inclinadas",Nivel="Intermediário",Resumo="Altura, rotações e esteiras inclinadas",Secoes={{"Como usar","{R} gira horizontalmente. Segure {R} e arraste a prévia para girar em outros eixos. Esteiras permitem inclinação de 45°."},{"Lembrete","{T} trava ou libera a altura. No celular/controle, use Subir/Descer. Alinhe as pontas e prepare uma correia onde o minério cair."}}}, {Id="elevador",Titulo="Elevador de minérios",Nivel="Intermediário",Resumo="Elevador de minérios",Secoes={{"Como usar","Gire a entrada com {R} e fixe sua posição. Mova o ponteiro para escolher a altura da saída, gire a face com {R} e clique para colocar. No celular ou controle, use Subir e Descer."},{"Lembrete","A seta âmbar marca a entrada, a turquesa marca a saída e a branca mostra a subida ou descida. Use Configurar elevador para ajustar uma peça já colocada."}}}, {Id="blueprints",Titulo="Blueprints: salvar e repetir conjuntos",Nivel="Intermediário",Resumo="Blueprints: salvar e repetir conjuntos",Secoes={{"Como usar","Abra Blueprints com {B}, selecione peças na plot e conclua a área para salvar o conjunto."},{"Lembrete","Ao recolocar, confira estoque, custo e posições bloqueadas. Blueprints permanecem após renascer, mas não concedem peças grátis."}}}, {Id="craft",Titulo="Craft: fabricar máquinas",Nivel="Avançado",Resumo="Craft: fabricar máquinas",Secoes={{"Como usar","Abra Craft e escolha uma receita. Toque num ingrediente de craft para abrir a receita dele."},{"Lembrete","Recolha os ingredientes para o inventário antes de fabricar. A confirmação consome as peças listadas e entrega uma máquina que permanece ao renascer."}}}, {Id="upgrades",Titulo="Upgrades: extração, fundição e motores",Nivel="Avançado",Resumo="Upgrades: extração, fundição e motores",Secoes={{"Como usar","Após o primeiro renascimento, compre melhorias de extração, fundição e motores em Upgrades ({U})."},{"Lembrete","Cada nível dá +{PASSO_UPGRADE}%, até {MAX_BONUS}%. Extração melhora o minério inicial; fundição, a venda. Motores libera velocidades maiores."}}}, {Id="calibracao-expansao",Titulo="Calibração e expansão da plot",Nivel="Avançado",Resumo="Calibração e expansão da plot",Secoes={{"Como usar","Após cinco renascimentos realizados, compre calibração e expansão. Calibração amplia a faixa de entrada aceita pelos modificadores."},{"Lembrete","Expansão aumenta a plot de 12³ até 32³ blocos e permanece após renascer. Todos os upgrades custam dinheiro."}}}, {Id="renascimento",Titulo="Prestígio: renascimento e salto de vidas",Nivel="Avançado",Resumo="Prestígio: renascimento e salto de vidas",Secoes={{"Como usar","Abra Prestígio com {P}. O primeiro requisito é 1Sx; cada reencarnação aumenta o requisito em ×1.000. Cada marco adicional de vida também é ×1.000."},{"Lembrete","Renascer reinicia dinheiro, peças comuns e upgrades do ciclo. Conserva blueprints, expansão, recompensas e recordes. Confira as vidas oferecidas antes de confirmar."}}}, {Id="recompensas",Titulo="Máquinas de renascimento",Nivel="Avançado",Resumo="Máquinas de renascimento",Secoes={{"Como usar","Cada renascimento entrega 1 ou 2 peças do conjunto atual. Complete cada conjunto em cinco ciclos. Cada vida extra sorteia mais uma peça entre os tipos já obtidos."},{"Lembrete","As recompensas permanecem e voltam ao inventário ao renascer. O limite de uso por minério não limita quantas cópias você pode guardar."}}}, {Id="fabrica-avancada",Titulo="Linhas compactas, junções e repetição de efeitos",Nivel="Avançado",Resumo="Linhas compactas, junções e repetição de efeitos",Secoes={{"Como usar","Reúna várias mineradoras numa linha comum. Atravesse modificadores em outros níveis e termine na fornalha."},{"Lembrete","Para repetir um efeito, saia da peça ou emissão antes de retornar. Respeite os usos e os limites de entrada."}}}, {Id="configuracoes",Titulo="Configurações, desempenho e confirmações",Nivel="Avançado",Resumo="Configurações, desempenho e confirmações",Secoes={{"Como usar","Ajuste minérios visíveis, valores, efeitos, escala da interface, prévia e grade em Configurações. Ocultar minérios não muda a produção."},{"Lembrete","Escolha confirmações de venda/renascimento, velocidade dos motores e teclas do PC. As preferências valem para a sessão."}}}, {Id="classificacao-mapa",Titulo="Visitar bases e disputar recordes",Nivel="Avançado",Resumo="Visitar bases e disputar recordes",Secoes={{"Como usar","A estrada acelera o trajeto entre as oito plots. Você continua podendo andar livremente."},{"Lembrete","Classificação mostra recordes globais de vidas, dinheiro/s, minério e saldo. A atualização pode levar algum tempo."}}}, {Id="diagnostico",Titulo="Diagnóstico e salvamento do progresso",Nivel="Avançado",Resumo="Diagnóstico e salvamento do progresso",Secoes={{"Como usar","Confira saída da mineradora, setas, alturas, faixas, limites e bandeja da fornalha. Acompanhe um minério até a venda."},{"Lembrete","Seu progresso e a plot são salvos automaticamente. Use blueprints para guardar montagens que queira repetir."}}}, }
function T.Normalizar(texto) for _,p in {{"á","Á","a"},{"à","À","a"},{"â","Â","a"},{"ã","Ã","a"},{"é","É","e"},{"ê","Ê","e"},{"í","Í","i"},{"ó","Ó","o"},{"ô","Ô","o"},{"õ","Õ","o"},{"ú","Ú","u"},{"ç","Ç","c"}} do texto=texto:gsub(p[1],p[3]):gsub(p[2],p[3]) end return texto:lower() end function T.Corresponde(licao,busca,nivel) if nivel and nivel~="Todos" and nivel~=licao.Nivel then return false end local textos={licao.Titulo,licao.Resumo,licao.Nivel} for _,s in licao.Secoes do table.insert(textos,s[1]); table.insert(textos,s[2]) end return T.Normalizar(table.concat(textos," ")):find(T.Normalizar(busca or ""),1,true)~=nil end function T.Formatar(texto,jogador) local tokens={BLOCO=tostring(Bloco),PLOT_INICIAL=tostring(Upgrades.TamanhosPlot[1]),PLOT_MAX=tostring(Upgrades.TamanhosPlot[#Upgrades.TamanhosPlot]), LIMITE_GRUPO=tostring(Limites.PecasPorGrupo),PASSO_UPGRADE=tostring(Upgrades.PercentualPorNivel),MAX_BONUS=tostring(Upgrades.PercentualPorNivel*#Upgrades.Itens[1].Precos)} local teclas={} for _,a in Config.Atalhos do table.insert(teclas,"["..Config.Tecla(jogador,a[1]).."] "..a[2]) end tokens.ATALHOS=table.concat(teclas,"\n") local resultado=texto:gsub("{([A-Z_]+)}",function(t) return tokens[t] or Config.Tecla(jogador,t) end) return resultado end return T

local Premios = require(script.Parent.RecompensasRenascimento) local Regra = {} local ordem = { Soltador = 1, Vendedor = 2, Modificador = 3 }
function Regra.Garantidas(ciclo) assert(type(ciclo) == "number" and ciclo >= 1 and ciclo % 1 == 0, "Ciclo invalido.") local marco = math.min(50, math.ceil(ciclo / 5) * 5) local lote = {} for _, premio in Premios do if premio.Lote == marco then table.insert(lote, premio) end end table.sort(lote, function(a, b) if ordem[a.Tipo] ~= ordem[b.Tipo] then return ordem[a.Tipo] < ordem[b.Tipo] end return (a.Codigo or a.Id) < (b.Codigo or b.Id) end) local passo = (ciclo - 1) % 5 + 1 local duplas = 10 - #lote local quantidade = if passo > duplas then 2 else 1 local inicio = passo - 1 + math.max(0, passo - 1 - duplas) local resultado = {} for i = 1, quantidade do table.insert(resultado, lote[(inicio + i - 1) % #lote + 1]) end return resultado end
return Regra
